"""ESPHome Light: puts the device in the OpenBridge graph (generated by `openbridge partner new`).
Identity is a salted pseudonym of the serial; the raw serial never reaches the snapshot."""
from src.fabric.contracts import Capability, DeviceObservation, Identifier, Link, now, opaque


def ingest_esphome_light(registry, device, salt, serial, emulated=True):
    status = 'SIMULATED_VERIFIED' if emulated else 'IMPLEMENTED_UNVERIFIED'
    t = now()
    try:
        facts = device.facts()
    except Exception as error:
        return {'status': 'UNAVAILABLE', 'detail': type(error).__name__}
    obs = [DeviceObservation(f['name'], f['value'], 'ESPHOME_LIGHT', 'LAN', t, True) for f in facts]
    key = registry.upsert([Identifier('esphome_light_serial', opaque('esphome_light_serial', serial, salt), True)],
                          category='lamp', label='ESPHome Light', observations=obs)
    registry.link(Link('pc', key, 'LAN', ('observe', 'read', 'control'), 'ESPHOME_LIGHT'))
    registry.capability(key, Capability('esphome_light_status', 'read', status, 'ESPHOME_LIGHT', 'facts read from the device'))
    registry.capability(key, Capability('esphome_light_setting', 'write', status, 'ESPHOME_LIGHT', 'typed settings, read back, exact Undo'))
    registry.capability(key, Capability('esphome_light_command', 'write', status, 'ESPHOME_LIGHT', 'momentary commands, consent per command'))
    return {'status': 'OK', 'devices': 1, 'emulated': emulated}
